with card_content(display_order, question_text, question_translation, answer_examples) as (
  values
    (11, 'Do you have children?', 'Você tem filhos?', '[{"answer":"No, I don''t.","translation":"Não, eu não tenho.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"Yes, I have one child.","translation":"Sim, eu tenho um filho/uma filha.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Yes, I have two children.","translation":"Sim, eu tenho dois filhos.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I have a son and a daughter.","translation":"Eu tenho um filho e uma filha.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Not yet, but I''d like to someday.","translation":"Ainda não, mas eu gostaria de ter um dia.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (12, 'Do you have any brothers or sisters?', 'Você tem irmãos ou irmãs?', '[{"answer":"Yes, I have one brother.","translation":"Sim, eu tenho um irmão.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I have two sisters.","translation":"Eu tenho duas irmãs.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I have a brother and a sister.","translation":"Eu tenho um irmão e uma irmã.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"No, I''m an only child.","translation":"Não, eu sou filho/a único/a.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Yes, I''m the youngest of three siblings.","translation":"Sim, eu sou o/a mais novo/a de três irmãos.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (13, 'Who do you live with?', 'Com quem você mora?', '[{"answer":"I live alone.","translation":"Eu moro sozinho/a.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I live with my parents.","translation":"Eu moro com meus pais.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I live with my partner.","translation":"Eu moro com meu/minha parceiro/a.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I live with my wife and children.","translation":"Eu moro com minha esposa e meus filhos.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I share an apartment with a friend.","translation":"Eu divido um apartamento com um amigo/uma amiga.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (14, 'Do you have any pets?', 'Você tem animais de estimação?', '[{"answer":"Yes, I have a dog.","translation":"Sim, eu tenho um cachorro.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I have two cats.","translation":"Eu tenho dois gatos.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"No, I don''t have any pets.","translation":"Não, eu não tenho animais de estimação.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I have a small dog named Max.","translation":"Eu tenho um cachorro pequeno chamado Max.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Not now, but I grew up with pets.","translation":"Agora não, mas eu cresci com animais de estimação.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (15, 'What''s your phone number?', 'Qual é o seu número de telefone?', '[{"answer":"It''s 555-0123.","translation":"É 555-0123.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"My number is 555-0187.","translation":"Meu número é 555-0187.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Sure, it''s 555-0142.","translation":"Claro, é 555-0142.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"Let me give you my number: 555-0199.","translation":"Deixe-me passar meu número: 555-0199.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''ll send you my number by message.","translation":"Eu vou te enviar meu número por mensagem.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (16, 'What''s your address?', 'Qual é o seu endereço?', '[{"answer":"I live on Main Street.","translation":"Eu moro na Rua Principal.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"My address is 25 Oak Street.","translation":"Meu endereço é Rua Oak, 25.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I live at 120 Central Avenue.","translation":"Eu moro na Avenida Central, 120.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I live near the main square.","translation":"Eu moro perto da praça principal.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I''ll send you the full address by message.","translation":"Eu vou te enviar o endereço completo por mensagem.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (17, 'What languages do you speak?', 'Quais idiomas você fala?', '[{"answer":"I speak Portuguese and English.","translation":"Eu falo português e inglês.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I speak Portuguese and a little Spanish.","translation":"Eu falo português e um pouco de espanhol.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Portuguese is my first language.","translation":"O português é a minha primeira língua.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I speak three languages: Portuguese, English, and Spanish.","translation":"Eu falo três idiomas: português, inglês e espanhol.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"I mainly speak Portuguese, but I''m learning English.","translation":"Eu falo principalmente português, mas estou aprendendo inglês.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (18, 'Are you learning any languages?', 'Você está aprendendo algum idioma?', '[{"answer":"Yes, I''m learning English.","translation":"Sim, eu estou aprendendo inglês.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I''m studying Spanish at the moment.","translation":"Eu estou estudando espanhol no momento.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Yes, I''m learning English for work.","translation":"Sim, eu estou aprendendo inglês para o trabalho.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I''m trying to improve my English speaking skills.","translation":"Eu estou tentando melhorar minha conversação em inglês.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"Not right now, but I''d like to learn Italian.","translation":"Agora não, mas eu gostaria de aprender italiano.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (19, 'What is your favorite language?', 'Qual é o seu idioma favorito?', '[{"answer":"English is my favorite language.","translation":"O inglês é o meu idioma favorito.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I really like Spanish.","translation":"Eu gosto muito de espanhol.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"Portuguese is still my favorite.","translation":"O português ainda é o meu favorito.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"I love the sound of Italian.","translation":"Eu adoro o som do italiano.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"It''s hard to choose, but I think English is my favorite.","translation":"É difícil escolher, mas acho que inglês é o meu favorito.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb),
    (20, 'What time do you usually wake up?', 'Que horas você costuma acordar?', '[{"answer":"I usually wake up at seven.","translation":"Eu geralmente acordo às sete.","note":"Resposta direta e neutra, adequada para a maioria das situações."},{"answer":"I get up around six thirty.","translation":"Eu levanto por volta das seis e meia.","note":"Opção natural e informal para conversas do dia a dia."},{"answer":"I normally wake up at eight.","translation":"Eu normalmente acordo às oito.","note":"Resposta um pouco mais detalhada, útil para manter a conversa."},{"answer":"On weekdays, I wake up at six.","translation":"Nos dias de semana, eu acordo às seis.","note":"Alternativa que acrescenta contexto e ajuda a desenvolver a interação."},{"answer":"It depends, but usually between seven and eight.","translation":"Depende, mas geralmente entre sete e oito.","note":"Resposta mais pessoal ou específica para quando você quiser elaborar."}]'::jsonb)
)
update public.conversation_questions as question
set question_text=content.question_text, question_translation=content.question_translation, answer_examples=content.answer_examples
from card_content as content where question.display_order=content.display_order;
